import { createClient } from '@clickhouse/client';
const client = createClient({ url: process.env.CLICKHOUSE_URL, username: 'default', password: '' });
try {
  if (!process.argv.includes('--readback')) {
    await client.command({ query: 'CREATE DATABASE IF NOT EXISTS analytics' });
    await client.command({ query: 'CREATE TABLE IF NOT EXISTS analytics.events (id UInt32, label String) ENGINE = MergeTree ORDER BY id' });
    await client.insert({ table: 'analytics.events', values: [{ id: 1, label: 'first event' }], format: 'JSONEachRow' });
  }
  const result = await client.query({ query: 'SELECT id, label FROM analytics.events ORDER BY id', format: 'JSONEachRow' });
  console.log(JSON.stringify(await result.json()));
} finally { await client.close(); }
